package com.spinplayer.app;
import org.schabi.newpipe.extractor.*;import org.schabi.newpipe.extractor.search.*;import org.schabi.newpipe.extractor.stream.*;import org.schabi.newpipe.extractor.playlist.*;import org.schabi.newpipe.extractor.linkhandler.*;import org.schabi.newpipe.extractor.localization.Localization;import java.util.*;import org.json.*;
public final class OnlineExtractor {
 private static boolean started=false;
 public static synchronized void init(){if(!started){NewPipe.init(new NetDownloader(),new Localization("en","GB"));started=true;}}
 public static StreamingService service(String source)throws Exception{return NewPipe.getService("SoundCloud".equals(source)?"SoundCloud":"YouTube");}
 public static void validate(String url)throws Exception{if(YandexCatalog.accepts(url)){new java.net.URI(url);return;}if(SpotifyCatalog.accepts(url)){SpotifyCatalog.parts(url);return;}java.net.URI u=new java.net.URI(url);String host=u.getHost();if(!"https".equalsIgnoreCase(u.getScheme())||host==null)throw new Exception("Вставь HTTPS-ссылку YouTube или SoundCloud");host=host.toLowerCase(java.util.Locale.ROOT);if(!(host.equals("youtu.be")||host.equals("youtube.com")||host.endsWith(".youtube.com")||host.equals("soundcloud.com")||host.endsWith(".soundcloud.com")||host.equals("on.soundcloud.com")))throw new Exception("Пока поддерживаются ссылки YouTube и SoundCloud");}
 public static String thumbnail(List<Image> images){if(images!=null)for(int i=images.size()-1;i>=0;i--)try{return ArtworkUrl.allowed(images.get(i).getUrl());}catch(Exception ignored){}return "";}
 static JSONObject item(InfoItem item)throws Exception{JSONObject j=new JSONObject().put("name",item.getName()).put("url",item.getUrl()).put("service",item.getServiceId()==1?"SoundCloud":"YouTube").put("cover",thumbnail(item.getThumbnails()));if(item instanceof StreamInfoItem){StreamInfoItem s=(StreamInfoItem)item;j.put("kind","track").put("artist",s.getUploaderName()).put("duration",s.getDuration()).put("verified",s.isUploaderVerified());}else if(item instanceof PlaylistInfoItem){j.put("kind","playlist").put("artist",((PlaylistInfoItem)item).getUploaderName());}else j.put("kind","other");if(j.optString("cover").isEmpty())j.put("cover",ArtworkUrl.fallback(item.getUrl()));return j;}
 public static JSONArray search(String query,String source)throws Exception{init();if(query.trim().length()<2)throw new Exception("Введи минимум два символа");StreamingService s=service(source);SearchInfo info=SearchInfo.getInfo(s,s.getSearchQHFactory().fromQuery(query,source.equals("YouTube Music")?Collections.singletonList("music_songs"):Collections.emptyList(),""));JSONArray result=new JSONArray();for(InfoItem i:info.getRelatedItems())if(i instanceof StreamInfoItem||i instanceof PlaylistInfoItem)result.put(item(i));return result;}
 public static JSONObject playlist(String url)throws Exception{init();validate(url);StreamingService service=NewPipe.getServiceByUrl(url);PlaylistInfo info=PlaylistInfo.getInfo(service,url);JSONArray list=new JSONArray();for(StreamInfoItem i:info.getRelatedItems())list.put(item(i));Page next=info.getNextPage();int pages=0;while(Page.isValid(next)&&list.length()<500&&pages++<20){ListExtractor.InfoItemsPage<StreamInfoItem> page=PlaylistInfo.getMoreItems(service,url,next);for(StreamInfoItem i:page.getItems())list.put(item(i));next=page.getNextPage();}return new JSONObject().put("name",info.getName()).put("tracks",list).put("limited",Page.isValid(next));}
 public static JSONObject resolve(String url)throws Exception{init();validate(url);StreamInfo info=StreamInfo.getInfo(url);JSONArray formats=new JSONArray();for(String[] f:new String[][]{{"best","Лучшее доступное · без перекодирования"},{"aac","M4A / AAC · если доступно"},{"opus","Opus · если доступно"}})formats.put(new JSONObject().put("key",f[0]).put("label",f[1]));return new JSONObject().put("name",info.getName()).put("artist",info.getUploaderName()).put("url",url).put("duration",info.getDuration()).put("service",url.contains("soundcloud.com")?"SoundCloud · экспериментально":"YouTube / YouTube Music").put("verified",info.isUploaderVerified()).put("cover",thumbnail(info.getThumbnails())).put("formats",formats);}
 public static JSONArray albums(String query)throws Exception{init();StreamingService s=service("YouTube");SearchInfo info=SearchInfo.getInfo(s,s.getSearchQHFactory().fromQuery(query,Collections.singletonList("music_albums"),""));JSONArray a=new JSONArray();for(InfoItem i:info.getRelatedItems())if(i instanceof PlaylistInfoItem)a.put(item(i));return a;}
 public static AudioStream stream(String url,String formatKey)throws Exception{init();validate(url);StreamInfo info=StreamInfo.getInfo(url);AudioStream best=null;for(AudioStream a:info.getAudioStreams()){if(!a.isUrl()||a.getDeliveryMethod()!=DeliveryMethod.PROGRESSIVE_HTTP||a.getFormat()==null)continue;if(a.getId().equals(formatKey))return a;if(best==null||a.getAverageBitrate()>best.getAverageBitrate())best=a;}if(best==null)throw new Exception("Нет доступного аудиопотока");if(!"best".equals(formatKey))throw new Exception("Выбранное качество больше не доступно. Выбери качество заново.");return best;}
}
